1	<!doctype html>
2	<html lang="zh-CN">
3	<meta charset="utf-8">
4	<meta name="viewport" content="width=device-width,initial-scale=1">
5	<title>ScoreArena · 桌面规则游戏与赛事管理</title>
6	<style>
7	  :root { color-scheme: light; }
8	  body { font-family: system-ui, sans-serif; max-width: 52rem; margin: 3rem auto; padding: 0 1rem; line-height: 1.7; color: #1f2933; }
9	  h1 { margin-bottom: .25rem; }
10	  .sub { color: #52606d; margin-top: 0; }
11	  h2 { margin-top: 2.5rem; border-bottom: 1px solid #e4e7eb; padding-bottom: .35rem; }
12	  a { color: #175b9c; }
13	  form { background: #f8f9fb; border: 1px solid #e4e7eb; border-radius: .5rem; padding: 1.25rem 1.5rem; }
14	  .field { display: grid; grid-template-columns: 9rem 1fr; gap: .75rem; align-items: center; margin-bottom: 1rem; }
15	  label { font-weight: 600; }
16	  input, select { font: inherit; padding: .4rem .55rem; border: 1px solid #cbd2d9; border-radius: .35rem; background: #fff; }
17	  input:focus, select:focus { outline: 2px solid #9ec5fe; outline-offset: 1px; border-color: #175b9c; }
18	  .hint { grid-column: 2; color: #616e7c; font-size: .9rem; margin: -.35rem 0 0; }
19	  .actions { grid-column: 2; margin-top: .25rem; }
20	  button { font: inherit; font-weight: 600; padding: .5rem 1.4rem; border: none; border-radius: .35rem; background: #175b9c; color: #fff; cursor: pointer; }
21	  button:disabled { background: #9aa5b1; cursor: wait; }
22	  .msg { margin: 1rem 0 0; padding: .6rem .9rem; border-radius: .35rem; display: none; }
23	  .msg.show { display: block; }
24	  .msg.error { background: #fde8e8; border: 1px solid #f5b5b5; color: #9b1c1c; }
25	  .msg.ok { background: #e6f6ec; border: 1px solid #a7e0bd; color: #146134; }
26	  table { width: 100%; border-collapse: collapse; font-size: .95rem; }
27	  th, td { text-align: left; padding: .55rem .6rem; border-bottom: 1px solid #e4e7eb; vertical-align: top; }
28	  th { color: #52606d; font-size: .85rem; white-space: nowrap; }
29	  td.id, code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .85rem; word-break: break-all; }
30	  .empty { color: #616e7c; }
31	  .skip-notice { background: #fff8e6; border: 1px solid #f0d48a; color: #7c4a03; padding: .6rem .9rem; border-radius: .35rem; margin: 0 0 1rem; }
32	  .list-error { color: #9b1c1c; }
33	  .badge { display: inline-block; padding: .05rem .55rem; border-radius: 999px; background: #fff3c4; color: #7c4a03; font-size: .85rem; }
34	  .meta { color: #7b8794; font-size: .85rem; }
35	</style>
36	<main>
37	  <h1>ScoreArena</h1>
38	  <p class="sub">桌面规则游戏与赛事管理</p>
39	
40	  <h2>创建公开房间</h2>
41	  <form id="room-form" novalidate>
42	    <div class="field">
43	      <label for="name">房间名称</label>
44	      <input id="name" name="name" type="text" autocomplete="off"
45	             placeholder="1–40 个字符，首尾空白会被去掉" required>
46	      <p class="hint">名称会去掉首尾空白后保存，内部空格保留；长度按 Unicode 字符计。原始输入不限长，整理后不超过 40 个字符即可。</p>
47	    </div>
48	    <div class="field">
49	      <label for="game">游戏规则</label>
50	      <select id="game" name="game" required>
51	        <option value="" selected>请选择游戏规则…</option>
52	        <option value="gomoku">五子棋（gomoku）</option>
53	        <option value="ludo">飞行棋（ludo）</option>
54	      </select>
55	    </div>
56	    <div class="field">
57	      <label for="capacity">人数上限</label>
58	      <select id="capacity" name="capacity" required disabled>
59	        <option value="" selected>请先选择游戏规则</option>
60	      </select>
61	      <p class="hint" id="capacity-hint">五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。</p>
62	    </div>
63	    <div class="field">
64	      <label for="turnSeconds">每步时间限制</label>
65	      <input id="turnSeconds" name="turnSeconds" type="number" step="1" inputmode="numeric"
66	             placeholder="秒，0 表示不限时" required>
67	      <p class="hint">以秒为单位：填 <strong>0</strong> 表示不限时；其他值必须是 10 至 600 之间的整数。</p>
68	    </div>
69	    <div class="field">
70	      <div></div>
71	      <div class="actions">
72	        <button type="submit" id="submit">创建房间</button>
73	      </div>
74	    </div>
75	    <p class="msg" id="form-msg" role="alert"></p>
76	  </form>
77	
78	  <h2>房间列表</h2>
79	  <div id="list-area">
80	    <p class="empty" id="empty-tip">还没有房间记录。</p>
81	  </div>
82	
83	  <p class="meta"><a href="/api/rooms">查看房间列表接口</a> · <a href="/health">服务状态</a></p>
84	</main>
85	
86	<script>
87	(function () {
88	  var form = document.getElementById('room-form');
89	  var gameSel = document.getElementById('game');
90	  var capSel = document.getElementById('capacity');
91	  var capHint = document.getElementById('capacity-hint');
92	  var submitBtn = document.getElementById('submit');
93	  var formMsg = document.getElementById('form-msg');
94	  var listArea = document.getElementById('list-area');
95	  var emptyTip = document.getElementById('empty-tip');
96	
97	  var GAME_LABELS = { gomoku: '五子棋', ludo: '飞行棋' };
98	  var STATUS_LABELS = { waiting: '未开始' };
99	
100	  // 按所选规则重建人数上限选项。
101	  function syncCapacity() {
102	    var game = gameSel.value;
103	    var prev = capSel.value;
104	    capSel.innerHTML = '';
105	    if (game === 'gomoku') {
106	      capSel.disabled = false;
107	      addOption('', '固定 2 人');
108	      addOption('2', '2 人');
109	      capSel.value = '2';
110	      capHint.textContent = '五子棋人数上限固定为 2 人。';
111	    } else if (game === 'ludo') {
112	      capSel.disabled = false;
113	      addOption('', '请选择人数上限…');
114	      [2, 3, 4].forEach(function (n) { addOption(String(n), n + ' 人'); });
115	      capSel.value = (prev === '2' || prev === '3' || prev === '4') ? prev : '';
116	      capHint.textContent = '飞行棋人数上限允许 2 至 4 人。';
117	    } else {
118	      capSel.disabled = true;
119	      addOption('', '请先选择游戏规则');
120	      capHint.textContent = '五子棋人数固定为 2 人；飞行棋允许 2 至 4 人。';
121	    }
122	  }
123	
124	  function addOption(value, text) {
125	    var opt = document.createElement('option');
126	    opt.value = value;
127	    opt.textContent = text;
128	    capSel.appendChild(opt);
129	  }
130	
131	  gameSel.addEventListener('change', syncCapacity);
132	
133	  function showMessage(kind, text) {
134	    formMsg.className = 'msg show ' + kind;
135	    formMsg.textContent = text;
136	  }
137	  function clearMessage() {
138	    formMsg.className = 'msg';
139	    formMsg.textContent = '';
140	  }
141	
142	  // 与服务端 strings.TrimSpace（Go unicode.IsSpace）完全一致的首尾空白范围：
143	  // 包含 U+0085、U+00A0 等，但不包含 U+FEFF（保留并计入长度）。
144	  // 不能用 JS 自带的 trim()：它会多去掉 U+FEFF，又漏掉 U+0085。
145	  var EDGE_SPACE = '[\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]';
146	  var LEADING_SPACE = new RegExp('^' + EDGE_SPACE + '+');
147	  var TRAILING_SPACE = new RegExp(EDGE_SPACE + '+$');
148	  function trimName(value) {
149	    return value.replace(LEADING_SPACE, '').replace(TRAILING_SPACE, '');
150	  }
151	
152	  // 与服务端一致的提交前校验；服务端仍会再次校验。
153	  function validate(payload) {
154	    var nameLen = Array.from(trimName(payload.name)).length;
155	    if (nameLen === 0) return '房间名称不能为空。';
156	    if (nameLen > 40) return '房间名称去掉首尾空白后不能超过 40 个字符。';
157	    if (payload.game !== 'gomoku' && payload.game !== 'ludo') return '请选择游戏规则。';
158	    if (payload.game === 'gomoku' && payload.capacity !== 2) return '五子棋的人数上限固定为 2 人。';
159	    if (payload.game === 'ludo' && !(payload.capacity >= 2 && payload.capacity <= 4)) {
160	      return '飞行棋的人数上限必须为 2 至 4 人。';
161	    }
162	    var t = payload.turnSeconds;
163	    if (t !== 0 && !(Number.isInteger(t) && t >= 10 && t <= 600)) {
164	      return '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。';
165	    }
166	    return null;
167	  }
168	
169	  form.addEventListener('submit', function (event) {
170	    event.preventDefault();
171	    clearMessage();
172	
173	    var nameInput = document.getElementById('name');
174	    var turnInput = document.getElementById('turnSeconds');
175	    var turnRaw = turnInput.value.trim();
176	    var payload = {
177	      name: nameInput.value,
178	      game: gameSel.value,
179	      capacity: capSel.value === '' ? null : parseInt(capSel.value, 10),
180	      turnSeconds: turnRaw === '' ? null : Number(turnRaw)
181	    };
182	
183	    // 漏填要明确报错，绝不补默认值；名称只含会被去掉的首尾空白时同样视为空。
184	    if (trimName(payload.name) === '') return showMessage('error', '房间名称不能为空。'), false;
185	    if (!payload.game) return showMessage('error', '请选择游戏规则。'), false;
186	    if (payload.capacity === null) return showMessage('error', '请选择人数上限。'), false;
187	    if (turnRaw === '') return showMessage('error', '请填写每步时间限制（0 表示不限时）。'), false;
188	    if (!/^-?\d+$/.test(turnRaw)) return showMessage('error', '时间限制必须是整数秒，不能含小数。'), false;
189	
190	    var problem = validate({
191	      name: payload.name,
192	      game: payload.game,
193	      capacity: payload.capacity,
194	      turnSeconds: Number(turnRaw)
195	    });
196	    if (problem) { showMessage('error', problem); return; }
197	
198	    payload.turnSeconds = Number(turnRaw);
199	    submit(payload);
200	  });
201	
202	  function submit(payload) {
203	    submitBtn.disabled = true;
204	    fetch('/api/rooms', {
205	      method: 'POST',
206	      headers: { 'Content-Type': 'application/json' },
207	      body: JSON.stringify(payload)
208	    }).then(function (resp) {
209	      return resp.json().catch(function () { return {}; }).then(function (data) {
210	        return { ok: resp.ok, status: resp.status, data: data };
211	      });
212	    }).then(function (result) {
213	      if (result.ok && result.status === 201) {
214	        showMessage('ok', '房间已创建，编号：' + result.data.id);
215	        form.reset();
216	        syncCapacity();
217	        return loadRooms();
218	      }
219	      // 创建失败：保留填写内容，仅显示原因。
220	      var reason = result.data && result.data.error ? result.data.error
221	                 : ('创建失败（HTTP ' + result.status + '）');
222	      showMessage('error', reason);
223	    }).catch(function () {
224	      showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
225	    }).finally(function () {
226	      submitBtn.disabled = false;
227	    });
228	  }
229	
230	  function formatTime(iso) {
231	    var d = new Date(iso);
232	    if (isNaN(d.getTime())) return iso;
233	    var pad = function (n) { return String(n).padStart(2, '0'); };
234	    var text = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
235	      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
236	    return { text: text, title: iso };
237	  }
238	
239	  // 只有 JSON 对象能作为房间行；null、字符串、数字、布尔值和数组都跳过。
240	  // 不按创建表单的规则重新判定历史记录：对象带多少附加字段都照常展示，
241	  // 也不检查其字段是否完整或合法（各单元格沿用现有兜底显示）。
242	  function isRoomRecord(value) {
243	    return value !== null && typeof value === 'object' && !Array.isArray(value);
244	  }
245	
246	  function appendSkipNotice(skipped, allSkipped) {
247	    var p = document.createElement('p');
248	    p.className = 'skip-notice';
249	    if (allSkipped) {
250	      p.textContent = '没有可展示的房间。本次返回的房间记录中有 ' + skipped +
251	        ' 条无法作为房间显示，已全部跳过；原始数据仍保留在服务端，未被删除或改写。';
252	    } else {
253	      p.textContent = '有 ' + skipped + ' 条房间记录无法作为房间显示，已跳过；' +
254	        '原始数据仍保留在服务端，未被删除或改写。';
255	    }
256	    listArea.appendChild(p);
257	  }
258	
259	  // 历史记录的某个展示字段若被存成 JSON 对象或数组，该单元格统一显示
260	  // “字段格式异常”，不展开其内部内容；异常只影响所在单元格，绝不能抛出
261	  // 异常拖垮整行乃至整份列表。null、字符串、数字、布尔值及缺失字段都不算
262	  // 异常，仍走各列原有的展示与兜底。
263	  var BAD_FIELD_TEXT = '字段格式异常';
264	  function isAbnormalField(value) {
265	    return value !== null && typeof value === 'object';
266	  }
267	  function markBadCell(td) {
268	    td.textContent = BAD_FIELD_TEXT;
269	  }
270	
271	  // 逐单元格渲染一个房间行：任何字段异常都只替换该单元格，其余字段照常显示。
272	  function buildRoomRow(r) {
273	    var tr = document.createElement('tr');
274	
275	    var tdId = document.createElement('td');
276	    tdId.className = 'id';
277	    if (isAbnormalField(r.id)) markBadCell(tdId);
278	    else tdId.textContent = r.id || '';
279	    tr.appendChild(tdId);
280	
281	    var tdName = document.createElement('td');
282	    if (isAbnormalField(r.name)) markBadCell(tdName);
283	    else tdName.textContent = r.name || '';
284	    tr.appendChild(tdName);
285	
286	    var tdGame = document.createElement('td');
287	    if (isAbnormalField(r.game)) markBadCell(tdGame);
288	    else tdGame.textContent = GAME_LABELS[r.game] || r.game || '';
289	    tr.appendChild(tdGame);
290	
291	    var tdCap = document.createElement('td');
292	    if (isAbnormalField(r.capacity)) markBadCell(tdCap);
293	    else tdCap.textContent = (r.capacity != null ? r.capacity : '') + ' 人';
294	    tr.appendChild(tdCap);
295	
296	    var tdTurn = document.createElement('td');
297	    if (isAbnormalField(r.turnSeconds)) {
298	      markBadCell(tdTurn);
299	    } else if (r.turnSeconds === 0) {
300	      tdTurn.textContent = '不限时';
301	    } else {
302	      tdTurn.textContent = r.turnSeconds + ' 秒';
303	    }
304	    tr.appendChild(tdTurn);
305	
306	    var tdStatus = document.createElement('td');
307	    var badge = document.createElement('span');
308	    badge.className = 'badge';
309	    if (isAbnormalField(r.status)) badge.textContent = BAD_FIELD_TEXT;
310	    else badge.textContent = STATUS_LABELS[r.status] || r.status || '';
311	    tdStatus.appendChild(badge);
312	    tr.appendChild(tdStatus);
313	
314	    var tdTime = document.createElement('td');
315	    if (isAbnormalField(r.createdAt)) {
316	      // 异常创建时间只显示异常文案，不附加日期悬浮说明（不设置 title）。
317	      markBadCell(tdTime);
318	    } else {
319	      var t = formatTime(r.createdAt || '');
320	      tdTime.textContent = t.text;
321	      tdTime.title = t.title;
322	    }
323	    tr.appendChild(tdTime);
324	
325	    return tr;
326	  }
327	
328	  function renderRooms(rooms) {
329	    listArea.innerHTML = '';
330	
331	    var validRooms = [];
332	    var skipped = 0;
333	    rooms.forEach(function (r) {
334	      if (isRoomRecord(r)) validRooms.push(r);
335	      else skipped++;
336	    });
337	
338	    if (!validRooms.length) {
339	      if (skipped > 0) {
340	        appendSkipNotice(skipped, true);
341	      } else {
342	        var pEmpty = document.createElement('p');
343	        pEmpty.className = 'empty';
344	        pEmpty.textContent = '还没有房间记录。';
345	        listArea.appendChild(pEmpty);
346	      }
347	      return;
348	    }
349	
350	    if (skipped > 0) appendSkipNotice(skipped, false);
351	
352	    var table = document.createElement('table');
353	    table.innerHTML =
354	      '<thead><tr>' +
355	      '<th>房间编号</th><th>名称</th><th>规则</th><th>人数上限</th>' +
356	      '<th>时间限制</th><th>状态</th><th>创建时间</th>' +
357	      '</tr></thead>';
358	    var tbody = document.createElement('tbody');
359	    validRooms.forEach(function (r) {
360	      tbody.appendChild(buildRoomRow(r));
361	    });
362	    table.appendChild(tbody);
363	    listArea.appendChild(table);
364	  }
365	
366	  // 列表查询序号：每次发起查询递增，只有当前最新一次查询的结果
367	  // （无论成功还是失败）允许更新列表区域；较早查询后返回的结果一律忽略，
368	  // 防止旧数据覆盖新查询已展示的列表。
369	  var listQuerySeq = 0;
370	
371	  function loadRooms() {
372	    var seq = ++listQuerySeq;
373	    return fetch('/api/rooms', { headers: { 'Accept': 'application/json' } })
374	      .then(function (resp) {
375	        if (!resp.ok) throw new Error('HTTP ' + resp.status);
376	        return resp.json();
377	      })
378	      .then(function (data) {
379	        if (seq !== listQuerySeq) return;
380	        var rooms = Array.isArray(data && data.rooms) ? data.rooms : [];
381	        renderRooms(rooms);
382	      })
383	      .catch(function () {
384	        if (seq !== listQuerySeq) return;
385	        listArea.innerHTML = '';
386	        var p = document.createElement('p');
387	        p.className = 'list-error';
388	        p.textContent = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
389	        listArea.appendChild(p);
390	      });
391	  }
392	
393	  syncCapacity();
394	  loadRooms();
395	})();
396	</script>
397	</html>
398

1	// 首页“创建公开房间”中“每步时间限制（turnSeconds）”的界面回归测试。
2	//
3	// 与另外两个浏览器回归文件的分工：
4	//   - ui.test.mjs：创建成功/被拒、成功后列表竞态刷新、名称整理与长度边界；
5	//   - ui-capacity-linkage.test.mjs：游戏规则与人数上限的联动；
6	//   - 本文件只盯住每步时间限制，把“时间输入 → 提交的请求体 → 创建结果 →
7	//     房间列表查询记录 → 新列表行展示”串起来断言。名称、规则与人数在每个
8	//     用例里都先填写合法值，由时间输入本身决定本次创建是否被允许。
9	//
10	// 覆盖的产品行为（五子棋与飞行棋共用同一套时间规则，人数仍按各自规则选择；
11	// 不改变名称整理、人数联动与其他已公开行为）：
12	//   - 明确填 0：成功创建不限时房间，提交 0（不是缺省），创建结果与列表查询
13	//     记录保存相同的 0，页面新行显示“不限时”；
14	//   - 10、600 两个端点以及区间内的整数（如 300）：都允许创建，三处保存相同
15	//     秒数，页面显示“N 秒”；端点必须包含在允许范围内；
