197	// trackRoomPosts 记录页面发出的每一次创建请求体，用于断言“页面直接拦截时
198	// 没有发出创建请求”以及“提交的 turnSeconds 就是用户选定值”。
199	function trackRoomPosts(page) {
200	  const bodies = [];
201	  page.on('request', (req) => {
202	    if (req.method() === 'POST' && req.url().endsWith('/api/rooms')) {
203	      bodies.push(req.postData());
