254	// expectBlocked 断言一次提交被“页面”直接拦截：显示页面自己的错误提示、
255	// 没有成功文案；不发出创建请求；服务端不增记录且编号集合不变；页面既有
256	// 列表逐格不变。返回拦截提示文本供后续比对。
257	async function expectBlocked(page, baseURL, postBodies, initialRows, expectedMsg) {
258	  await page.click('#submit');
259	  await waitForMessageKind(page, 'error');
260	  const msg = await readMessage(page);
261	  assert.equal(msg.text, expectedMsg, '应显示页面侧的时间错误提示');
262	  assert.ok(!msg.className.includes('ok'), '被拦截时不应显示成功提示');
263	  assert.ok(!msg.text.includes(SUCCESS_PREFIX), '被拦截时不应出现成功编号');
264	  assert.ok(!msg.text.includes('已创建'), '被拦截时不应出现成功文案');
265	
266	  // 关键区分：页面直接拦截，必须没有发出任何创建请求；
267	  // 若请求被发出、仅靠服务端拒绝，本断言会失败。
268	  await sleep(300);
269	  assert.equal(postBodies.length, 0, '页面拦截时不应发出创建请求');
270	
271	  const serverRooms = await readServerRooms(baseURL);
272	  assert.equal(serverRooms.length, 2, '服务端房间列表不应增加记录');
273	  assert.deepEqual(
274	    serverRooms.map((r) => r.id),
275	    ['seed-alpha', 'seed-beta'],
276	    '服务端不得出现任何新编号',
277	  );
278	  assert.deepEqual(await readRows(page), initialRows, '页面上的既有列表不应变化');
279	  return msg.text;
280	}
